1	/**
2	 * Destination map — lives in inbound.db's `destinations` table.
3	 *
4	 * The host writes this table before every container wake AND on demand
5	 * (e.g. when a new child agent is created mid-session). The container
6	 * queries the table live on every lookup, so admin changes take effect
7	 * immediately — no restart required.
8	 *
9	 * This table is BOTH the routing map and the container-visible ACL.
10	 * The host re-validates on the delivery side against the central DB,
11	 * so even if this table is stale the host's enforcement is authoritative.
12	 */
13	import { getInboundDb } from './db/connection.js';
14	
15	export interface DestinationEntry {
16	  name: string;
17	  displayName: string;
18	  type: 'channel' | 'agent';
19	  channelType?: string;
20	  platformId?: string;
21	  agentGroupId?: string;
22	}
23	
24	interface DestRow {
25	  name: string;
26	  display_name: string | null;
27	  type: 'channel' | 'agent';
28	  channel_type: string | null;
29	  platform_id: string | null;
30	  agent_group_id: string | null;
31	}
32	
33	function rowToEntry(row: DestRow): DestinationEntry {
34	  return {
35	    name: row.name,
36	    displayName: row.display_name ?? row.name,
37	    type: row.type,
38	    channelType: row.channel_type ?? undefined,
39	    platformId: row.platform_id ?? undefined,
40	    agentGroupId: row.agent_group_id ?? undefined,
41	  };
42	}
43	
44	export function getAllDestinations(): DestinationEntry[] {
45	  const rows = getInboundDb().prepare('SELECT * FROM destinations ORDER BY name').all() as DestRow[];
46	  return rows.map(rowToEntry);
47	}
48	
49	export function findByName(name: string): DestinationEntry | undefined {
50	  const row = getInboundDb().prepare('SELECT * FROM destinations WHERE name = ?').get(name) as DestRow | undefined;
51	  return row ? rowToEntry(row) : undefined;
52	}
53	
54	/**
55	 * Reverse lookup: given routing fields from an inbound message, find
56	 * which destination they correspond to (what does this agent call the sender?).
57	 */
58	export function findByRouting(
59	  channelType: string | null | undefined,
60	  platformId: string | null | undefined,
61	): DestinationEntry | undefined {
62	  if (!channelType || !platformId) return undefined;
63	  const db = getInboundDb();
64	  const row =
65	    channelType === 'agent'
66	      ? (db
67	          .prepare("SELECT * FROM destinations WHERE type = 'agent' AND agent_group_id = ?")
68	          .get(platformId) as DestRow | undefined)
69	      : (db
70	          .prepare("SELECT * FROM destinations WHERE type = 'channel' AND channel_type = ? AND platform_id = ?")
71	          .get(channelType, platformId) as DestRow | undefined);
72	  return row ? rowToEntry(row) : undefined;
73	}
74	
75	/**
76	 * Generate the system-prompt addendum: agent identity + destination map.
77	 *
78	 * Identity is injected here (not in the shared CLAUDE.md) because it's
79	 * per-agent-group and changes when the operator renames an agent, while
80	 * the shared base is identical across all agents.
81	 */
82	export function buildSystemPromptAddendum(assistantName?: string): string {
83	  const sections: string[] = [];
84	
85	  if (assistantName) {
86	    sections.push(['# You are ' + assistantName, '', `Your name is **${assistantName}**. Use it when the channel asks who you are, when introducing yourself, and when signing any message that explicitly calls for a signature.`].join('\n'));
87	  }
88	
89	  sections.push(buildDestinationsSection());
90	
91	  return sections.join('\n\n');
92	}
93	
94	function buildDestinationsSection(): string {
95	  const all = getAllDestinations();
96	
97	  if (all.length === 0) {
98	    return [
99	      '## Sending messages',
100	      '',
101	      'You currently have no configured destinations. You cannot send messages until an admin wires one up.',
102	    ].join('\n');
103	  }
104	
105	  const lines = ['## Sending messages', ''];
106	  if (all.length === 1) {
107	    const d = all[0];
108	    const label = d.displayName && d.displayName !== d.name ? ` (${d.displayName})` : '';
109	    lines.push(`Your destination is \`${d.name}\`${label}.`);
110	  } else {
111	    lines.push('You can send messages to the following destinations:', '');
112	    for (const d of all) {
113	      const label = d.displayName && d.displayName !== d.name ? ` (${d.displayName})` : '';
114	      lines.push(`- \`${d.name}\`${label}`);
115	    }
116	  }
117	  lines.push('');
118	  lines.push(
119	    'Wrap each delivered message in a `<message to="name">…</message>` block; include several blocks in one response to address several destinations. `<internal>…</internal>` marks thinking you don\'t want sent.',
120	  );
121	  lines.push('');
122	  lines.push(
123	    'When replying to an incoming message, default to addressing the destination it came `from` (every inbound `<message>` tag carries a `from="name"` attribute). Pick a different destination when the request asks for it (e.g., "tell Laura that…").',
124	  );
125	  lines.push('');
126	  lines.push(
127	    'The `send_message` MCP tool is the same delivery, available mid-turn — handy for a quick acknowledgment ("on it") before a slow tool call. Each `send_message` call and each final-response `<message>` block lands as its own message in the conversation, so they read as a sequence rather than as one combined reply.',
128	  );
129	  return lines.join('\n');
130	}
