43	/**
44	 * Write a cli_request to outbound.db.
45	 *
46	 * Uses BEGIN IMMEDIATE to acquire a write lock before reading max(seq),
47	 * preventing seq collisions with concurrent agent-runner writes.
48	 */
49	function writeRequest(req: RequestFrame): void {
50	  const db = new Database(OUTBOUND_DB);
51	  db.exec('PRAGMA journal_mode = DELETE');
52	  db.exec('PRAGMA busy_timeout = 5000');
53	
54	  const inDb = new Database(INBOUND_DB, { readonly: true });
55	  inDb.exec('PRAGMA busy_timeout = 5000');
56	
57	  try {
58	    db.exec('BEGIN IMMEDIATE');
59	    const maxOut = (db.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_out').get() as { m: number }).m;
60	    const maxIn = (inDb.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_in').get() as { m: number }).m;
61	    const max = Math.max(maxOut, maxIn);
62	    const nextSeq = max % 2 === 0 ? max + 1 : max + 2;
63	
64	    db.prepare(
65	      `INSERT INTO messages_out (id, seq, timestamp, kind, content)
66	       VALUES ($id, $seq, datetime('now'), 'system', $content)`,
67	    ).run({
68	      $id: req.id,
69	      $seq: nextSeq,
70	      $content: JSON.stringify({
71	        action: 'cli_request',
72	        requestId: req.id,
73	        command: req.command,
74	        args: req.args,
75	      }),
76	    });
77	    db.exec('COMMIT');
78	  } catch (e) {
79	    db.exec('ROLLBACK');
80	    throw e;
81	  } finally {
82	    inDb.close();
83	    db.close();
84	  }
85	}
